/* Common header for the MMBCC decompdecomp save.
 * The universal scalar typedefs every matched function compiled with
 * in the pret-style project (identical in every source file there).
 * All other declarations stay in each function's own .c file, because
 * the same name is declared with different types in different files.
 * Generated by build.py; do not hand-edit. */
#ifndef MMBCC_COMMON_H
#define MMBCC_COMMON_H

typedef signed char s8;
typedef unsigned short u16;
typedef unsigned int u32;
typedef unsigned long long u64;
typedef unsigned char u8;
typedef volatile unsigned char vu8;

#endif /* MMBCC_COMMON_H */
